var a=[{title:`Bancs pour l’appui et les développés`,text:`Un banc plat soutient les développés, les rowings et les mouvements assis. Un banc réglable change l’angle de votre torse pour les développés et d’autres exercices. Vérifiez que sa capacité indiquée couvre votre poids plus toute charge externe, verrouillez le réglage et assurez-vous qu’il ne bascule ni ne glisse avant de le charger. Une chaise n’est pas automatiquement un banc de musculation sûr.`},{title:`Une marche stable`,text:`Les montées sur marche, les pompes inclinées et le cardio sur petite marche demandent une plateforme qui ne bascule pas. Commencez avec une marche basse qui laisse votre hanche et votre genou bouger avec contrôle. Posez tout le pied d’appui sur la marche, redescendez de façon délibérée et ne vous poussez pas avec le pied arrière pour compenser une plateforme trop haute.`},{title:`Ajuster une corde à sauter`,text:`Comme premier repère approximatif, placez un pied au milieu de la corde et soulevez les poignées. Beaucoup de cordes de loisir conviennent quand les poignées arrivent à peu près au bas de la poitrine ou aux aisselles, même si le modèle de corde et le niveau changent la longueur idéale. Une corde trop courte touche vos pieds. Une corde trop longue accroche le sol et peut entraîner de grands cercles des bras.`},{title:`Vérifiez l’espace et le matériel`,text:`Utilisez un sol antidérapant et faites attention aux meubles, aux lampes, aux ventilateurs et aux autres personnes. La corde à sauter demande de la place au-dessus et sur les côtés autant qu’au sol. Avant chaque séance, vérifiez l’usure du revêtement des cordes, les extrémités de câble tranchantes, les charnières de banc abîmées et les surfaces de marche mal fixées. Remplacez le matériel cassé au lieu de bricoler des réparations.`},{title:`Avec TrainUp`,text:`Indiquez dans Profil votre type de banc, la taille de votre espace au sol, la hauteur de votre plafond, votre surface et si vous pouvez sauter, et le programme ne choisit que des exercices adaptés. Si vos genoux ou votre espace excluent une marche, ou si le bruit, l’impact ou la hauteur de plafond excluent la corde, les exercices sans marche et la marche sur place sont les alternatives.`}];var t=[{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic : sécurité et technique en musculation`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};